s=s[:pos]+'''function serializeError(error: Error, superJson: SuperJSON): any {
  const options = superJson.errorStack;
  if (!options) {
    const result: any = { name: error.name, message: error.message };
    if ('cause' in error) result.cause = error.cause;
    superJson.allowedErrorProps.forEach(prop => { result[prop] = (error as any)[prop]; });
    return superJson.errorClassRegistry.getProcessor(error.name)?.(result) ?? result;
  }

  const seen = new Set<Error>();
  function build(current: Error, depth: number, sanitizeCause: boolean): any {
    seen.add(current);
    const matches = !options!.classFilter.length || options!.classFilter.includes(current.name);
    const sanitize = options!.sanitizeMessage && (matches || sanitizeCause);
    const result: any = { name: current.name, message: sanitize ? sanitizeMessage(current.message) : current.message };
    superJson.allowedErrorProps.forEach(prop => {
      if (prop !== 'stack' && prop !== 'stackFrames' && prop !== 'cause' && prop !== 'errors') result[prop] = (current as any)[prop];
    });
    if (matches && typeof current.stack === 'string') {
      if (options!.mode === 'string' && superJson.allowedErrorProps.includes('stack')) result.stack = processStackString(current.stack, options!);
      if (options!.mode === 'frames' && superJson.allowedErrorProps.includes('stackFrames')) result.stackFrames = processStackFrames(current.stack, options!);
    }
    if (typeof AggregateError !== 'undefined' && current instanceof AggregateError) result.errors = current.errors;
    const cause = current.cause;
    const limit = options!.includeCauses === 'direct' ? 1 : options!.includeCauses === 'deep' ? options!.maxCauseDepth : 0;
    if (depth < limit && isError(cause) && !seen.has(cause)) result.cause = build(cause, depth + 1, sanitize);
    return superJson.errorClassRegistry.getProcessor(current.name)?.(result) ?? result;
  }
  return build(error, 0, false);
}

function deserializeError(v: any, superJson: SuperJSON): Error {
  function restore(value: any): Error {
    const e = Object.prototype.hasOwnProperty.call(value, 'errors') && typeof AggregateError !== 'undefined'
      ? new AggregateError(value.errors, value.message, { cause: value.cause })
      : new Error(value.message, { cause: value.cause });
    e.name = value.name;
    e.stack = value.stack;
    if (value.stackFrames !== undefined) (e as any).stackFrames = value.stackFrames;
    if (value.cause && !(value.cause instanceof Error) && typeof value.cause === 'object' && typeof value.cause.name === 'string' && typeof value.cause.message === 'string') e.cause = restore(value.cause);
    superJson.allowedErrorProps.forEach(prop => {
      if (Object.prototype.hasOwnProperty.call(value, prop)) (e as any)[prop] = value[prop];
    });
    return e;
  }
